const dataRaw=$('Attempts Range').first().json||{};
const countRaw=$('Count Range').first().json||{};
const rowsAll=Array.isArray(dataRaw.data)?dataRaw.data:null;
const countRows=Array.isArray(countRaw.data)?countRaw.data:null;
const expected=countRows?.[0]?.count?.id;
const meta=$('Validate Range').first().json;
if(!rowsAll || expected===undefined || expected===null){
  return [{json:{ok:false,error:'Directus non ha restituito una risposta valida. Nessun KPI viene calcolato.',error_code:'DB_RESPONSE_INVALID'}}];
}
const expectedN=Number(expected||0);
if(rowsAll.length!==expectedN){
  return [{json:{ok:false,error:`Dataset parziale: ricevute ${rowsAll.length} righe su ${expectedN}. Nessun KPI viene calcolato.`,error_code:'DATASET_TRUNCATED',rows_returned:rowsAll.length,rows_expected:expectedN}}];
}
const prodVal=v=>v===false||v===0||String(v).toLowerCase()==='false';
const testVal=v=>v===true||v===1||String(v).toLowerCase()==='true';
const rows=rowsAll.filter(a=>prodVal(a.test_mode));
const testCount=rowsAll.filter(a=>testVal(a.test_mode)).length;
const envUnknown=rowsAll.length-rows.length-testCount;
const div=(a,b)=>b?a/b:null;
const bump=(o,k)=>{const key=(k===null||k===undefined||String(k).trim()==='')?'missing':String(k);o[key]=(o[key]||0)+1};
const validRespondent=v=>['human','ivr','ai_voice','voicemail'].includes(String(v||'').toLowerCase());
const purposeAnalysisAvailable=v=>!['','unknown','unkown'].includes(String(v??'').trim().toLowerCase());
const purposeDetermined=v=>['commercial','support','private','reception'].includes(String(v||'').toLowerCase());
const serviceDetermined=v=>!['','unknown','unkown','none'].includes(String(v??'').trim().toLowerCase());
const purpose={},service_category={};let completed=0,spam=0,rOk=0,pAnalysis=0,pDetermined=0,sDetermined=0;const buckets={};
for(let dt=DateTime.fromISO(meta.from_local,{zone:'Europe/Rome'});dt<=DateTime.fromISO(meta.to_local,{zone:'Europe/Rome'});dt=dt.plus({days:1}))buckets[dt.toISODate()]={date:dt.toISODate(),calls_registered:0,completed:0,spam:0,respondent_ok:0};
for(const a of rows){
  const dt=DateTime.fromISO(a.start_time,{setZone:true});
  const local=dt.isValid?dt.setZone('Europe/Rome').toISODate():null;
  const b=local?buckets[local]:null;if(b)b.calls_registered++;
  if(a.call_status!=='completed')continue;
  completed++;if(b)b.completed++;
  bump(purpose,a.purpose);bump(service_category,a.service_category);
  if(a.verdict==='spam'){spam++;if(b)b.spam++;}
  const rok=validRespondent(a.respondent_type);const pa=purposeAnalysisAvailable(a.purpose);const pd=rok&&purposeDetermined(a.purpose);const sd=pd&&serviceDetermined(a.service_category);
  if(rok){rOk++;if(b)b.respondent_ok++;}if(pa)pAnalysis++;if(pd)pDetermined++;if(sd)sDetermined++;
}
const steps=[['Chiamate con start_time registrato',rows.length,'A'],['Conversazioni completate',completed,'A'],['Interlocutore determinato',rOk,'B'],['Finalità determinata',pDetermined,'B'],['Categoria/settore determinata',sDetermined,'B']];
const funnel=steps.map((s,i)=>({label:s[0],count:s[1],reliability:s[2],of_total:div(s[1],steps[0][1]),of_previous:i?div(s[1],steps[i-1][1]):1,drop:i?steps[i-1][1]-s[1]:0,drop_rate:i?div(steps[i-1][1]-s[1],steps[i-1][1]):0}));
const dropoff=funnel.slice(1).map((s,i)=>({label:i===0?'Esito tecnico diverso da completed':`${s.label}: non determinato`,drop:s.drop,drop_rate:s.drop_rate,of_total:div(s.drop,steps[0][1])}));
const trend=Object.values(buckets).map(b=>({...b,attempts:b.calls_registered,completed_rate:div(b.completed,b.calls_registered),spam_rate_completed:div(b.spam,b.completed),respondent_coverage:div(b.respondent_ok,b.completed)}));
const warnings=[];if(envUnknown>0)warnings.push(`${envUnknown} record nel periodo hanno ambiente non certificabile e sono esclusi dai KPI produzione.`);
return [{json:{ok:true,generated_at:new Date().toISOString(),range:{from:meta.from_local,to:meta.to_local,days:meta.days,timezone:'Europe/Rome',basis:'mt_call_attempts.start_time'},scope:{production_rule:'test_mode === false',production_rows:rows.length,test_rows_excluded:testCount,environment_unknown_excluded:envUnknown,total_rows_in_range:rowsAll.length},macro:{attempts:rows.length,completed,completed_rate:div(completed,rows.length),spam,spam_rate_completed:div(spam,completed),respondent_coverage:div(rOk,completed),purpose_analysis_available_rate:div(pAnalysis,completed),purpose_determined_rate:div(pDetermined,completed),service_determined_rate:div(sDetermined,completed)},funnel,dropoff,purpose,service_category,trend,data_quality:{respondent_missing:completed-rOk,purpose_analysis_missing:completed-pAnalysis,purpose_not_determined:completed-pDetermined,service_not_determined:completed-sDetermined,test_excluded:testCount,environment_unknown:envUnknown},source_integrity:{rows_expected:expectedN,rows_returned:rowsAll.length,complete:true},warnings}}];

/* ============================================================
   TAG CONVERSAZIONI - passo 1: perimetro e lettura tag dalla lista.
   Unico blocco della tab Analisi che NON legge da Directus.
   Fonte: API conversazioni ElevenLabs (agente Angela).
   ============================================================ */
const meta = $('Validate Range').first().json;
const DA = meta.from_local;   // YYYY-MM-DD
const A  = meta.to_local;     // YYYY-MM-DD

const TZ = 'Europe/Rome';
// Tetto di sicurezza: se i tag NON sono nella lista, il fallback sul
// dettaglio conversazione parte solo sotto questa soglia, per non fare
// centinaia di chiamate a ogni refresh della dashboard.
const MAX_DETTAGLI = 120;

const daUnix = Math.floor(DateTime.fromISO(DA + 'T00:00:00', { zone: TZ }).toSeconds());
const aUnix  = Math.floor(DateTime.fromISO(A  + 'T23:59:59', { zone: TZ }).toSeconds());

/* ---------- estrazione tag ----------------------------------------
   ElevenLabs non espone i tag sempre nello stesso campo: a seconda
   della versione API stanno sulla conversazione, dentro metadata o
   dentro analysis. Invece di fissare un percorso si cerca qualsiasi
   chiave "tags"/"labels" con valori stringa, saltando i rami pesanti
   (transcript, audio). Il campo effettivamente trovato finisce in
   tags.diag.campi_tag, cosi' e' verificabile con una sola chiamata. */
const CHIAVI_TAG = /^(tags|tag|labels|conversation_tags|conversation_labels)$/i;
const SALTA = new Set(['transcript', 'messages', 'audio', 'transcript_summary']);

function normalizzaTag(v, prof){
  prof = prof || 0;
  if (v == null || prof > 3) return [];
  if (typeof v === 'string'){
    const s = v.trim();
    if (!s) return [];
    if (s.startsWith('[') || s.startsWith('{')){
      try { return normalizzaTag(JSON.parse(s), prof + 1); } catch(e){}
    }
    return s.split(',').map(x => x.trim()).filter(Boolean);
  }
  if (Array.isArray(v)) return v.flatMap(x => normalizzaTag(x, prof + 1));
  if (typeof v === 'object'){
    const n = v.name ?? v.tag ?? v.label ?? v.value ?? v.tag_name ?? v.title;
    return n == null ? [] : normalizzaTag(String(n), prof + 1);
  }
  return [];
}

function cercaTag(obj, prof, trovati, chiavi){
  prof = prof || 0;
  if (!obj || typeof obj !== 'object' || prof > 4) return;
  for (const k of Object.keys(obj)){
    if (SALTA.has(k)) continue;
    const v = obj[k];
    if (CHIAVI_TAG.test(k)){
      const t = normalizzaTag(v);
      if (t.length){ trovati.push(...t); chiavi.add(k); }
      continue;
    }
    if (v && typeof v === 'object') cercaTag(v, prof + 1, trovati, chiavi);
  }
}

function tagDi(obj, chiavi){
  const trovati = [];
  cercaTag(obj, 0, trovati, chiavi);
  const visti = new Map();
  for (const t of trovati){
    const k = String(t).trim().toLowerCase();
    if (k && !visti.has(k)) visti.set(k, String(t).trim());
  }
  return [...visti.values()];
}

/* ---------- lista conversazioni ---------- */
function pagine(nome){ try { return $(nome).all().map(x => x.json); } catch(e){ return []; } }

const pg = pagine('Tag Lista ElevenLabs');
const haRisposto = pg.some(p => p && Array.isArray(p.conversations));
const grezze = pg.flatMap(p => (p && Array.isArray(p.conversations)) ? p.conversations : []);

const perId = new Map();
for (const c of grezze){
  const k = c && (c.conversation_id || c.id);
  if (k && !perId.has(k)) perId.set(k, c);
}

function inizio(c){
  let s = Number(c.start_time_unix_secs ?? c.start_time_unix ?? 0);
  if (!isFinite(s) || s <= 0) return 0;
  if (s > 1e12) s = Math.floor(s / 1000);
  return s;
}

// Il filtro a monte usa solo call_start_after_unix (parametro certo);
// il taglio superiore del range si fa qui, in locale.
const chiavi = new Set();
const conversazioni = [];
let fuoriRange = 0, senzaData = 0;

for (const [id, c] of perId){
  const s = inizio(c);
  if (!s) senzaData++;
  else if (s < daUnix || s > aUnix){ fuoriRange++; continue; }
  conversazioni.push({ id, unix: s, tags: tagDi(c, chiavi) });
}

const conTagInLista = conversazioni.filter(c => c.tags.length).length;

// Il dettaglio serve solo se la lista non porta tag per nessuno.
const serveDettaglio = haRisposto
  && conTagInLista === 0
  && conversazioni.length > 0
  && conversazioni.length <= MAX_DETTAGLI;

const prima = grezze[0] && typeof grezze[0] === 'object' ? Object.keys(grezze[0]) : [];

const riepilogo = {
  ha_risposto: haRisposto,
  range: { from: DA, to: A, from_unix: daUnix, to_unix: aUnix },
  conversazioni,
  diag: {
    pagine_ricevute: pg.length,
    conversazioni_grezze: grezze.length,
    nel_range: conversazioni.length,
    fuori_range: fuoriRange,
    senza_data: senzaData,
    con_tag_in_lista: conTagInLista,
    campi_tag: [...chiavi],
    chiavi_lista: prima.slice(0, 40),
    fallback_dettaglio: serveDettaglio,
    fallback_max: MAX_DETTAGLI,
    fallback_saltato_per_volume: haRisposto && conTagInLista === 0 && conversazioni.length > MAX_DETTAGLI
  }
};

if (!serveDettaglio) return [{ json: { riepilogo, nulla_da_leggere: true } }];

return conversazioni.map((c, i) => ({
  json: i === 0 ? { riepilogo, conversation_id: c.id } : { conversation_id: c.id }
}));

/* ============================================================
   TAG CONVERSAZIONI - passo 2: conteggi e merge nella risposta.
   La risposta Directus resta identica: si aggiunge solo "tags".
   ============================================================ */
const base = $('Aggregate Analysis').first().json || {};

const prep = $('Tag Prepara').first().json || {};
const riepilogo = prep.riepilogo || {};

/* stessa estrazione del nodo "Tag Prepara", qui applicata al dettaglio */
const CHIAVI_TAG = /^(tags|tag|labels|conversation_tags|conversation_labels)$/i;
const SALTA = new Set(['transcript', 'messages', 'audio', 'transcript_summary']);

function normalizzaTag(v, prof){
  prof = prof || 0;
  if (v == null || prof > 3) return [];
  if (typeof v === 'string'){
    const s = v.trim();
    if (!s) return [];
    if (s.startsWith('[') || s.startsWith('{')){
      try { return normalizzaTag(JSON.parse(s), prof + 1); } catch(e){}
    }
    return s.split(',').map(x => x.trim()).filter(Boolean);
  }
  if (Array.isArray(v)) return v.flatMap(x => normalizzaTag(x, prof + 1));
  if (typeof v === 'object'){
    const n = v.name ?? v.tag ?? v.label ?? v.value ?? v.tag_name ?? v.title;
    return n == null ? [] : normalizzaTag(String(n), prof + 1);
  }
  return [];
}
function cercaTag(obj, prof, trovati, chiavi){
  prof = prof || 0;
  if (!obj || typeof obj !== 'object' || prof > 4) return;
  for (const k of Object.keys(obj)){
    if (SALTA.has(k)) continue;
    const v = obj[k];
    if (CHIAVI_TAG.test(k)){
      const t = normalizzaTag(v);
      if (t.length){ trovati.push(...t); chiavi.add(k); }
      continue;
    }
    if (v && typeof v === 'object') cercaTag(v, prof + 1, trovati, chiavi);
  }
}
function tagDi(obj, chiavi){
  const trovati = [];
  cercaTag(obj, 0, trovati, chiavi);
  const visti = new Map();
  for (const t of trovati){
    const k = String(t).trim().toLowerCase();
    if (k && !visti.has(k)) visti.set(k, String(t).trim());
  }
  return [...visti.values()];
}

const conversazioni = Array.isArray(riepilogo.conversazioni)
  ? riepilogo.conversazioni.map(c => ({ id: c.id, unix: c.unix, tags: [...(c.tags || [])] }))
  : [];

/* merge dei tag letti dal dettaglio, quando il fallback e' scattato */
const chiavi = new Set(riepilogo.diag?.campi_tag || []);
function dettagli(){ try { return $('Tag Dettaglio Conversazione').all().map(x => x.json); } catch(e){ return []; } }

const indice = new Map(conversazioni.map(c => [c.id, c]));
let dettagliLetti = 0, chiaviDettaglio = [];
for (const d of dettagli()){
  if (!d || typeof d !== 'object') continue;
  const id = d.conversation_id || d.id;
  if (!id) continue;
  dettagliLetti++;
  if (!chiaviDettaglio.length) chiaviDettaglio = Object.keys(d).slice(0, 40);
  const t = tagDi(d, chiavi);
  const c = indice.get(id);
  if (c && t.length) c.tags = [...new Set([...c.tags, ...t])];
}

/* ---------- conteggi ----------
   Una conversazione puo' avere piu' tag: "items" conta le assegnazioni,
   non le conversazioni. "untagged" conta invece conversazioni intere,
   ed e' la fetta "Senza tag" della torta. */
const conteggi = new Map();
let conTag = 0, assegnazioni = 0, multiTag = 0;
for (const c of conversazioni){
  const t = c.tags || [];
  if (!t.length) continue;
  conTag++;
  if (t.length > 1) multiTag++;
  for (const x of t){
    conteggi.set(x, (conteggi.get(x) || 0) + 1);
    assegnazioni++;
  }
}

const items = [...conteggi.entries()]
  .map(([tag, count]) => ({ tag, count, share: assegnazioni ? count / assegnazioni : null }))
  .sort((a, b) => (b.count - a.count) || a.tag.localeCompare(b.tag, 'it'));

const disponibile = riepilogo.ha_risposto === true;

const tags = disponibile ? {
  available: true,
  source: 'elevenlabs',
  basis: 'conversazioni ElevenLabs con avvio nel range selezionato',
  range: riepilogo.range || null,
  conversations_total: conversazioni.length,
  conversations_with_tags: conTag,
  untagged: conversazioni.length - conTag,
  multi_tag_conversations: multiTag,
  assignments_total: assegnazioni,
  distinct_tags: items.length,
  items,
  diag: Object.assign({}, riepilogo.diag, {
    dettagli_letti: dettagliLetti,
    campi_tag: [...chiavi],
    chiavi_dettaglio: chiaviDettaglio
  })
} : {
  available: false,
  source: 'elevenlabs',
  error: 'ElevenLabs non ha restituito la lista conversazioni',
  range: riepilogo.range || null,
  diag: riepilogo.diag || null
};

return [{ json: Object.assign({}, base, { tags }) }];
